<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence;
use App\Application\Read\Page;
final class PdoReportRepository extends PdoRepository
{
    private function query(string $sql,array $params=[]):array{$s=$this->pdo()->prepare($sql);$s->execute($params);return$s->fetchAll();}
    private function scope(string $column,?array $allowed,array &$params):string{if($allowed===null)return'';if($allowed===[])return' AND 1=0';foreach($allowed as$id)$params[]=(int)$id;return' AND '.$column.' IN('.implode(',',array_fill(0,count($allowed),'?')).')';}
    private function base(array$f,string$branch,string$date,?array$allowed,array&$p):string{$p=[$f['from'].' 00:00:00',$f['to'].' 23:59:59.999999'];$w=" WHERE $date BETWEEN ? AND ?".$this->scope($branch,$allowed,$p);if($f['branch']!==null){$w.=" AND $branch=?";$p[]=$f['branch'];}return$w;}
    public function report(array$f,?array$allowed,int$limit=25,int$offset=0):array
    {
        if($limit<1||$limit>\App\Application\Reporting\ReportExportPolicy::MAX_ROWS||$offset<0)throw new \InvalidArgumentException('Límites de reporte inválidos.');
        return match($f['type']){'quotes'=>$this->quotes($f,$allowed,$limit,$offset),'inventory'=>$this->inventory($f,$allowed,$limit,$offset),'movements'=>$this->movements($f,$allowed,$limit,$offset),'shortages'=>$this->shortages($f,$allowed,$limit,$offset),'purchases'=>$this->purchases($f,$allowed,$limit,$offset),'transfers'=>$this->transfers($f,$allowed,$limit,$offset),'deliveries'=>$this->deliveries($f,$allowed,$limit,$offset),'partial_deliveries'=>$this->partialDeliveries($f,$allowed,$limit,$offset),'imports'=>$this->imports($f,$limit,$offset),'audit'=>$this->audit($f,$allowed,$limit,$offset),default=>throw new \InvalidArgumentException('Reporte inválido.')};
    }
    private function page(array$rows,int$limit,int$offset):Page{$more=count($rows)>$limit;if($more)array_pop($rows);return new Page($rows,$limit,$offset,$more);}
    private function quotes(array$f,?array$a,int$l,int$o):array
    {
        $universe="(SELECT q.id quote_id,COALESCE(w.folio,p.folio,q.folio) folio,w.branch_id,COALESCE(p.created_at,w.created_at) received_at,q.status document_status,w.origin,w.full_name customer,v.total,w.assigned_user_id,(SELECT MIN(e.created_at) FROM quote_workflow_events e WHERE e.workflow_id=w.id AND e.action IN('take','contact','prepare')) first_attention_at FROM quote_workflows w LEFT JOIN public_quote_requests p ON p.id=w.request_id LEFT JOIN quotes q ON q.id=w.quote_id LEFT JOIN quote_versions v ON v.quote_id=q.id AND v.version_number=q.current_version UNION ALL SELECT q.id,COALESCE(p.folio,q.folio),p.branch_id,p.created_at,q.status,'web',p.full_name,v.total,p.assigned_user_id,NULL FROM public_quote_requests p LEFT JOIN quotes q ON q.id=p.quote_id LEFT JOIN quote_versions v ON v.quote_id=q.id AND v.version_number=q.current_version WHERE NOT EXISTS(SELECT 1 FROM quote_workflows w WHERE w.request_id=p.id OR (q.id IS NOT NULL AND w.quote_id=q.id)) UNION ALL SELECT q.id,q.folio,q.branch_id,q.created_at,q.status,'internal',c.legal_name,v.total,q.assigned_user_id,NULL FROM quotes q JOIN customers c ON c.id=q.customer_id JOIN quote_versions v ON v.quote_id=q.id AND v.version_number=q.current_version WHERE NOT EXISTS(SELECT 1 FROM quote_workflows w WHERE w.quote_id=q.id) AND NOT EXISTS(SELECT 1 FROM public_quote_requests p WHERE p.quote_id=q.id)) r";
        $p=[];$w=$this->base($f,'r.branch_id','r.received_at',$a,$p);if($f['status']!==''){$w.=' AND r.document_status=?';$p[]=$f['status'];}if($f['origin']!==''){$w.=' AND r.origin=?';$p[]=$f['origin'];}if($f['q']!==''){$w.=' AND (r.folio LIKE ? OR r.customer LIKE ?)';$t='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$t,$t);}
        $join=' FROM '.$universe.' JOIN branches b ON b.id=r.branch_id LEFT JOIN users seller ON seller.id=r.assigned_user_id';
        $summary=$this->query("SELECT COUNT(*) total,COALESCE(SUM(r.document_status='accepted'),0) accepted,COALESCE(SUM(r.document_status='rejected'),0) rejected,COALESCE(SUM(r.document_status='cancelled'),0) cancelled,COALESCE(SUM(r.document_status IS NULL OR r.document_status IN('received','assigned','preparing','pending_approval','sent')),0) pending,COALESCE(SUM(CASE WHEN r.document_status<>'cancelled' OR r.document_status IS NULL THEN COALESCE(r.total,0) ELSE 0 END),0) estimated,ROUND(AVG(CASE WHEN r.first_attention_at>=r.received_at THEN TIMESTAMPDIFF(MINUTE,r.received_at,r.first_attention_at) END),1) first_attention_minutes,MAX(CASE WHEN r.document_status IS NULL OR r.document_status IN('received','assigned','preparing','pending_approval','sent') THEN GREATEST(0,DATEDIFF(CURRENT_DATE,DATE(r.received_at))) ELSE 0 END) oldest_pending_days".$join.$w,$p)[0];
        $series=$this->query('SELECT DATE(r.received_at) label,COUNT(*) value'.$join.$w.' GROUP BY DATE(r.received_at) ORDER BY label',$p);$states=$this->query("SELECT COALESCE(r.document_status,'received') label,COUNT(*) value".$join.$w." GROUP BY COALESCE(r.document_status,'received') ORDER BY value DESC,label",$p);$channels=$this->query('SELECT r.origin label,COUNT(*) value'.$join.$w.' GROUP BY r.origin ORDER BY value DESC,label',$p);$branches=$this->query('SELECT b.name label,COUNT(*) value'.$join.$w.' GROUP BY b.id,b.name ORDER BY value DESC,label',$p);$sellers=$this->query("SELECT COALESCE(seller.display_name,'Sin asignar') label,COUNT(*) value".$join.$w." GROUP BY r.assigned_user_id,seller.display_name ORDER BY value DESC,label",$p);
        $rows=$this->query("SELECT r.quote_id id,r.folio,r.customer,b.name branch,COALESCE(seller.display_name,'Sin asignar') seller,COALESCE(r.document_status,'received') status,r.origin,COALESCE(r.total,0) total,DATE(r.received_at) created_date,GREATEST(0,DATEDIFF(CURRENT_DATE,DATE(r.received_at))) age_days".$join.$w.' ORDER BY r.received_at DESC,r.folio DESC LIMIT '.($l+1).' OFFSET '.$o,$p);
        return['title'=>'Cotizaciones y solicitudes','summary'=>$summary,'series'=>$series,'states'=>$states,'channels'=>$channels,'branches'=>$branches,'sellers'=>$sellers,'page'=>$this->page($rows,$l,$o),'columns'=>['Folio','Cliente','Sucursal','Vendedor','Estado','Canal','Total estimado MXN','Fecha de recepción','Antigüedad (días)'],'keys'=>['folio','customer','branch','seller','status','origin','total','created_date','age_days'],'date_basis'=>'Universo único desde la recepción original, incluso sin documento comercial. Primera atención: primer evento operativo posterior a la recepción; solicitudes convertidas no se duplican. El total es valor estimado documental, no ingreso.'];
    }
    private function inventory(array$f,?array$a,int$l,int$o):array
    {
        $p=[];$w=' WHERE 1=1'.$this->scope('ib.branch_id',$a,$p);if($f['branch']!==null){$w.=' AND ib.branch_id=?';$p[]=$f['branch'];}if($f['status']==='low')$w.=' AND st.minimum_quantity IS NOT NULL AND ib.available_quantity<=st.minimum_quantity';if($f['q']!==''){$w.=' AND (p.name LIKE ? OR v.sku LIKE ?)';$t='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$t,$t);}
        $join=' FROM inventory_balances ib JOIN branches b ON b.id=ib.branch_id JOIN product_variants v ON v.id=ib.variant_id JOIN products p ON p.id=v.product_id JOIN units u ON u.id=v.unit_id LEFT JOIN stock_thresholds st ON st.branch_id=ib.branch_id AND st.variant_id=ib.variant_id';
        $s=$this->query('SELECT COUNT(*) total,COALESCE(SUM(ib.physical_quantity>0),0) physical,COALESCE(SUM(ib.reserved_quantity>0),0) reserved,COALESCE(SUM(ib.available_quantity>0),0) available,COALESCE(SUM(st.minimum_quantity IS NOT NULL AND ib.available_quantity<=st.minimum_quantity),0) low'.$join.$w,$p)[0];
        $rows=$this->query('SELECT v.sku,p.name product,v.name variant,b.name branch,u.symbol,ib.physical_quantity physical,ib.reserved_quantity reserved,ib.available_quantity available,st.minimum_quantity minimum'.$join.$w.' ORDER BY p.name,v.sku,b.name LIMIT '.($l+1).' OFFSET '.$o,$p);
        return['title'=>'Inventario','summary'=>$s,'series'=>[],'states'=>[],'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['SKU','Producto','Variante','Sucursal','Unidad','Existencia física','Apartado','Disponible','Mínimo'],'keys'=>['sku','product','variant','branch','symbol','physical','reserved','available','minimum'],'date_basis'=>'Saldo actual del inventario; disponible = físico − apartado. Los indicadores cuentan saldos por variante y sucursal; no suman piezas, metros o kilogramos incompatibles.'];
    }
    private function movements(array$f,?array$a,int$l,int$o):array
    {$p=[];$w=$this->base($f,'m.branch_id','m.created_at',$a,$p);if($f['status']!==''){$w.=' AND m.movement_type=?';$p[]=$f['status'];}if($f['q']!==''){$w.=' AND (v.sku LIKE ? OR pr.name LIKE ? OR m.reason LIKE ? OR m.source_id LIKE ?)';$t='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$t,$t,$t,$t);}$j=' FROM inventory_movements m JOIN branches b ON b.id=m.branch_id JOIN product_variants v ON v.id=m.variant_id JOIN products pr ON pr.id=v.product_id JOIN units u ON u.id=v.unit_id JOIN users actor ON actor.id=m.actor_user_id';$states=$this->query('SELECT m.movement_type label,COUNT(*) value'.$j.$w.' GROUP BY m.movement_type ORDER BY value DESC,label',$p);$sum=['total'=>array_sum(array_map(fn($r)=>(int)$r['value'],$states))];$rows=$this->query('SELECT DATE(m.created_at) movement_date,v.sku,pr.name product,b.name branch,m.movement_type,u.symbol,m.base_quantity,m.physical_before,m.physical_after,m.reason,actor.display_name actor'.$j.$w.' ORDER BY m.created_at DESC,m.id DESC LIMIT '.($l+1).' OFFSET '.$o,$p);return['title'=>'Kardex y movimientos','summary'=>$sum,'series'=>[],'states'=>$states,'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['Fecha','SKU','Producto','Sucursal','Movimiento','Unidad base','Cantidad','Físico anterior','Físico posterior','Motivo','Actor'],'keys'=>['movement_date','sku','product','branch','movement_type','symbol','base_quantity','physical_before','physical_after','reason','actor'],'date_basis'=>'Fecha real del movimiento inmutable. Las cantidades se expresan en la unidad base indicada para cada variante.'];}
    private function shortages(array$f,?array$a,int$l,int$o):array
    {$p=[];$w=' WHERE st.minimum_quantity IS NOT NULL AND ib.available_quantity<=st.minimum_quantity'.$this->scope('ib.branch_id',$a,$p);if($f['branch']!==null){$w.=' AND ib.branch_id=?';$p[]=$f['branch'];}if($f['status']==='exhausted')$w.=' AND ib.available_quantity=0';elseif($f['status']==='low')$w.=' AND ib.available_quantity>0';if($f['q']!==''){$w.=' AND (v.sku LIKE ? OR pr.name LIKE ?)';$t='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$t,$t);}$j=' FROM inventory_balances ib JOIN stock_thresholds st ON st.branch_id=ib.branch_id AND st.variant_id=ib.variant_id JOIN branches b ON b.id=ib.branch_id JOIN product_variants v ON v.id=ib.variant_id JOIN products pr ON pr.id=v.product_id JOIN units u ON u.id=v.unit_id';$sum=$this->query('SELECT COUNT(*) total,COALESCE(SUM(ib.available_quantity=0),0) exhausted,COALESCE(SUM(ib.available_quantity>0),0) low'.$j.$w,$p)[0];$states=[['label'=>'exhausted','value'=>$sum['exhausted']],['label'=>'low','value'=>$sum['low']]];$rows=$this->query("SELECT v.sku,pr.name product,b.name branch,u.symbol,ib.physical_quantity physical,ib.reserved_quantity reserved,ib.available_quantity available,st.minimum_quantity minimum,IF(ib.available_quantity=0,'exhausted','low') status".$j.$w.' ORDER BY ib.available_quantity,pr.name,v.sku,b.name LIMIT '.($l+1).' OFFSET '.$o,$p);return['title'=>'Mínimos y agotados','summary'=>$sum,'series'=>[],'states'=>$states,'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['SKU','Producto','Sucursal','Unidad','Físico','Apartado','Disponible','Mínimo','Estado'],'keys'=>['sku','product','branch','symbol','physical','reserved','available','minimum','status'],'date_basis'=>'Saldo actual por variante y sucursal comparado con el mínimo configurado; agotado significa disponible igual a cero.'];}
    private function purchases(array$f,?array$a,int$l,int$o):array
    {$p=[];$w=$this->base($f,'i.branch_id','i.document_date',$a,$p);if($f['status']!==''){$w.=' AND i.status=?';$p[]=$f['status'];}if($f['q']!==''){$w.=' AND (i.folio LIKE ? OR s.legal_name LIKE ?)';$t='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$t,$t);}$j=' FROM supplier_invoices i JOIN suppliers s ON s.id=i.supplier_id JOIN branches b ON b.id=i.branch_id';$sum=$this->query('SELECT COUNT(*) total,COALESCE(SUM(i.status=\'received\'),0) completed,COALESCE(SUM(i.status=\'partial\'),0) partial,COALESCE(SUM(CASE WHEN i.status<>\'cancelled\' THEN i.total ELSE 0 END),0) documented'.$j.$w,$p)[0];$states=$this->query('SELECT i.status label,COUNT(*) value'.$j.$w.' GROUP BY i.status ORDER BY value DESC',$p);$rows=$this->query('SELECT i.folio,s.legal_name supplier,b.name branch,i.document_date,i.status,i.currency,i.total'.$j.$w.' ORDER BY i.document_date DESC,i.id DESC LIMIT '.($l+1).' OFFSET '.$o,$p);return['title'=>'Compras','summary'=>$sum,'series'=>[],'states'=>$states,'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['Folio','Proveedor','Sucursal','Fecha documento','Estado','Moneda','Total documentado'],'keys'=>['folio','supplier','branch','document_date','status','currency','total'],'date_basis'=>'Fecha del documento del proveedor; importes documentados, no pagos.'];}
    private function transfers(array$f,?array$a,int$l,int$o):array
    {$p=[$f['from'].' 00:00:00',$f['to'].' 23:59:59.999999'];$w=' WHERE t.created_at BETWEEN ? AND ?';if($a!==null){if(!$a)$w.=' AND 1=0';else{foreach($a as$id){$p[]=$id;$p[]=$id;}$w.=' AND ('.implode(' OR ',array_fill(0,count($a),'t.source_branch_id=? OR t.destination_branch_id=?')).')';}}if($f['branch']!==null){$w.=' AND (t.source_branch_id=? OR t.destination_branch_id=?)';array_push($p,$f['branch'],$f['branch']);}if($f['status']!==''){$w.=' AND t.status=?';$p[]=$f['status'];}if($f['q']!==''){$w.=' AND (t.folio LIKE ? OR t.reason LIKE ?)';$x='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$x,$x);}$j=' FROM transfers t JOIN branches bs ON bs.id=t.source_branch_id JOIN branches bd ON bd.id=t.destination_branch_id';$states=$this->query('SELECT t.status label,COUNT(*) value'.$j.$w.' GROUP BY t.status ORDER BY value DESC',$p);$sum=['total'=>array_sum(array_map(fn($r)=>(int)$r['value'],$states))];foreach($states as$r)$sum[$r['label']]=$r['value'];$rows=$this->query('SELECT t.folio,bs.name source,bd.name destination,t.status,t.reason,DATE(t.created_at) created_date'.$j.$w.' ORDER BY t.created_at DESC,t.id DESC LIMIT '.($l+1).' OFFSET '.$o,$p);return['title'=>'Transferencias','summary'=>$sum,'series'=>[],'states'=>$states,'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['Folio','Origen','Destino','Estado','Motivo','Fecha de solicitud'],'keys'=>['folio','source','destination','status','reason','created_date'],'date_basis'=>'Fecha de creación de la solicitud; el alcance incluye origen o destino autorizado.'];}
    private function deliveries(array$f,?array$a,int$l,int$o):array
    {$p=[];$w=$this->base($f,'d.branch_id','d.created_at',$a,$p);if($f['status']!==''){$w.=' AND d.status=?';$p[]=$f['status'];}if($f['q']!==''){$w.=' AND (d.folio LIKE ? OR c.legal_name LIKE ?)';$x='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$x,$x);}$j=' FROM deliveries d JOIN branches b ON b.id=d.branch_id JOIN customers c ON c.id=d.customer_id JOIN quote_versions v ON v.id=d.quote_version_id JOIN quotes q ON q.id=v.quote_id';$states=$this->query('SELECT d.status label,COUNT(*) value'.$j.$w.' GROUP BY d.status ORDER BY value DESC',$p);$sum=['total'=>array_sum(array_map(fn($r)=>(int)$r['value'],$states)),'pending'=>0,'completed'=>0,'incidents'=>0];foreach($states as$r){if($r['label']==='delivered')$sum['completed']=$r['value'];elseif($r['label']==='failed')$sum['incidents']=$r['value'];elseif($r['label']!=='cancelled')$sum['pending']+=(int)$r['value'];}$rows=$this->query('SELECT d.folio,q.folio quote,c.legal_name customer,b.name branch,d.mode,d.status,d.scheduled_date,d.delivery_cost'.$j.$w.' ORDER BY d.created_at DESC,d.id DESC LIMIT '.($l+1).' OFFSET '.$o,$p);return['title'=>'Entregas','summary'=>$sum,'series'=>[],'states'=>$states,'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['Folio','Cotización','Cliente','Sucursal','Modalidad','Estado','Fecha programada','Costo entrega MXN'],'keys'=>['folio','quote','customer','branch','mode','status','scheduled_date','delivery_cost'],'date_basis'=>'Fecha de creación de la entrega; la fecha programada se muestra como atributo operativo.'];}
    private function partialDeliveries(array$f,?array$a,int$l,int$o):array
    {$p=[];$w=$this->base($f,'d.branch_id','d.created_at',$a,$p);$state="CASE WHEN di.received_quantity=di.quantity THEN 'completed' WHEN di.received_quantity>0 OR di.dispatched_quantity>0 THEN 'partial' ELSE 'pending' END";if($f['status']!==''){$w.=' AND '.$state.'=?';$p[]=$f['status'];}if($f['q']!==''){$w.=' AND (d.folio LIKE ? OR q.folio LIKE ? OR c.legal_name LIKE ? OR qi.sku LIKE ?)';$x='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$x,$x,$x,$x);}$j=' FROM delivery_items di JOIN deliveries d ON d.id=di.delivery_id JOIN quote_items qi ON qi.id=di.quote_item_id JOIN quote_versions v ON v.id=d.quote_version_id JOIN quotes q ON q.id=v.quote_id JOIN customers c ON c.id=d.customer_id JOIN branches b ON b.id=d.branch_id JOIN units u ON u.id=qi.unit_id';$states=$this->query('SELECT '.$state.' label,COUNT(*) value'.$j.$w.' GROUP BY '.$state.' ORDER BY value DESC',$p);$sum=['total'=>array_sum(array_map(fn($r)=>(int)$r['value'],$states)),'pending'=>0,'partial'=>0,'completed'=>0];foreach($states as$r)$sum[$r['label']]=$r['value'];$rows=$this->query('SELECT d.folio,q.folio quote,c.legal_name customer,b.name branch,qi.sku,qi.description,u.symbol,di.quantity,di.dispatched_quantity dispatched,di.received_quantity received,'.$state.' status'.$j.$w.' ORDER BY d.created_at DESC,d.id DESC,di.id LIMIT '.($l+1).' OFFSET '.$o,$p);return['title'=>'Entregas parciales','summary'=>$sum,'series'=>[],'states'=>$states,'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['Entrega','Cotización','Cliente','Sucursal','SKU','Partida','Unidad','Programado','Despachado','Recibido','Estado'],'keys'=>['folio','quote','customer','branch','sku','description','symbol','quantity','dispatched','received','status'],'date_basis'=>'Partidas de entrega dentro del periodo de creación; el estado parcial se calcula con cantidades despachadas y recibidas sin sumar unidades incompatibles.'];}
    private function imports(array$f,int$l,int$o):array
    {$p=[$f['from'].' 00:00:00',$f['to'].' 23:59:59.999999'];$w=' WHERE r.created_at BETWEEN ? AND ?';if($f['status']!==''){$w.=' AND r.status=?';$p[]=$f['status'];}if($f['q']!==''){$w.=' AND (r.source_name LIKE ? OR r.token LIKE ? OR u.display_name LIKE ?)';$x='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$x,$x,$x);}$j=' FROM catalog_import_runs r JOIN users u ON u.id=r.actor_user_id';$states=$this->query('SELECT r.status label,COUNT(*) value'.$j.$w.' GROUP BY r.status ORDER BY value DESC',$p);$sum=$this->query('SELECT COUNT(*) total,COALESCE(SUM(r.status=\'confirmed\'),0) confirmed,COALESCE(SUM(r.rejected_rows),0) errors,COALESCE(SUM(r.created_products),0) created'.$j.$w,$p)[0];$rows=$this->query('SELECT r.source_name,LEFT(r.token,12) reference,u.display_name actor,r.status,r.total_rows,r.accepted_rows,r.rejected_rows,r.created_products,DATE(r.created_at) created_date,DATE(r.confirmed_at) confirmed_date'.$j.$w.' ORDER BY r.created_at DESC,r.id DESC LIMIT '.($l+1).' OFFSET '.$o,$p);return['title'=>'Importaciones y errores','summary'=>$sum,'series'=>[],'states'=>$states,'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['Archivo','Referencia','Actor','Estado','Filas','Aceptadas','Rechazadas','Productos creados','Vista previa','Confirmación'],'keys'=>['source_name','reference','actor','status','total_rows','accepted_rows','rejected_rows','created_products','created_date','confirmed_date'],'date_basis'=>'Historial durable de vistas previas y confirmaciones. Las filas rechazadas son errores de validación; una confirmación repetida no duplica productos.'];}
    private function audit(array$f,?array$a,int$l,int$o):array
    {$p=[$f['from'].' 00:00:00',$f['to'].' 23:59:59.999999'];$w=' WHERE a.created_at BETWEEN ? AND ?';if($a!==null){if($a===[])$w.=' AND 1=0';else{$w.=' AND (a.branch_id IS NULL OR a.branch_id IN('.implode(',',array_fill(0,count($a),'?')).'))';foreach($a as$id)$p[]=(int)$id;}}if($f['branch']!==null){$w.=' AND a.branch_id=?';$p[]=$f['branch'];}if($f['status']!==''){$w.=' AND a.outcome=?';$p[]=$f['status'];}if($f['q']!==''){$w.=' AND (a.action LIKE ? OR a.resource LIKE ? OR a.resource_id LIKE ? OR u.display_name LIKE ?)';$x='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$x,$x,$x,$x);}$j=' FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_user_id LEFT JOIN branches b ON b.id=a.branch_id';$states=$this->query('SELECT a.outcome label,COUNT(*) value'.$j.$w.' GROUP BY a.outcome ORDER BY value DESC',$p);$sum=['total'=>array_sum(array_map(fn($r)=>(int)$r['value'],$states)),'success'=>0,'failure'=>0,'denied'=>0];foreach($states as$r)$sum[$r['label']]=$r['value'];$rows=$this->query("SELECT DATE(a.created_at) event_date,COALESCE(u.display_name,'Sistema') actor,a.action,a.resource,a.resource_id,COALESCE(b.name,'Global') branch,a.outcome".$j.$w.' ORDER BY a.created_at DESC,a.id DESC LIMIT '.($l+1).' OFFSET '.$o,$p);return['title'=>'Auditoría','summary'=>$sum,'series'=>[],'states'=>$states,'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['Fecha','Actor','Acción','Recurso','ID recurso','Sucursal','Resultado'],'keys'=>['event_date','actor','action','resource','resource_id','branch','outcome'],'date_basis'=>'Eventos de auditoría dentro del permiso audit.view; no se exportan hashes, IP ni diagnóstico privado.'];}
}
